#include <iostream>
#include <cmath>

int main() {
    int h, n;
    std::cin >> h >> n;
    n = n - 1 + (1 << h);
    int count = h;
    int i = 1;
    while (i <= h) {
        int current_bit = n & (1 << i);
        int previous_bit = n & (1 << (i - 1));
        if (!(((current_bit == 0) ? 1 : 0) ^ ((previous_bit == 0) ? 1 : 0))) {
            count += (1 << i) - 1;
        }
        i++;
    }
    std::cout << count << std::endl;
    return 0;
}
